/**
 * @file src/lib/rocketTrustTooltip.ts
 * Custom tooltip HTML for Team Rocket Trust KPI (XP progress + sources).
 */

import {
  ROCKET_TRUST_XP_WEIGHTS,
  MIAOUSS_STATUETTE_BUNDLE,
} from '../../constants/balance/teamRocket.js';
import { formatNumber } from '../../formatters.ts';
import { uiText } from '../ui/i18n.ts';
import type { GameRuntime } from '../types/game.js';
import type { RocketTrustLevelInfo } from '../types/game/state.js';

function trUi(
  game: GameRuntime,
  key: string,
  fallback: string,
  vars: Record<string, unknown> = {},
): string {
  return uiText(`teamRocket.${key}`, fallback, vars, game);
}

function escapeTooltipHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

export interface RocketTrustTooltipContent {
  title: string;
  bodyHtml: string;
}

export function buildRocketTrustTooltip(
  game: GameRuntime,
  trustInfo: RocketTrustLevelInfo,
  rankLabel: string,
): RocketTrustTooltipContent {
  const fmt = (v: number) => formatNumber(v);
  const level = Math.floor(Number(trustInfo.currentLevel) || 1);
  const title = trUi(game, 'trustTooltipTitle', '{rank} — Niv. {level}', { rank: rankLabel, level });

  const xpLabel = trustInfo.isMax
    ? trUi(game, 'trustMaxLevel', 'Max level reached')
    : trUi(game, 'trustXpProgress', '{current} / {next} XP', {
        current: fmt(trustInfo.currentXp),
        next: fmt(trustInfo.nextLevelXp),
      });

  const ratioPct = Math.max(0, Math.min(100, trustInfo.ratio * 100));

  const sources = [
    {
      label: trUi(game, 'trustTooltipSourceQuest', 'Quête Team Rocket (réclamation)'),
      xp: ROCKET_TRUST_XP_WEIGHTS.quest,
    },
    {
      label: trUi(game, 'trustTooltipSourceCapture', 'Capture Miaouss / Persian'),
      xp: ROCKET_TRUST_XP_WEIGHTS.capture,
    },
    {
      label: trUi(game, 'trustTooltipSourceStaking', 'Session staking Push Your Luck'),
      xp: ROCKET_TRUST_XP_WEIGHTS.staking,
    },
    {
      label: trUi(game, 'trustTooltipSourceSpin', 'Spin machine à sous'),
      xp: ROCKET_TRUST_XP_WEIGHTS.spin,
    },
    {
      label: trUi(game, 'trustTooltipSourceStatuette', 'Statuette Miaouss (objet)'),
      xp: MIAOUSS_STATUETTE_BUNDLE.trustXp,
    },
  ];

  const sourcesTitle = trUi(game, 'trustTooltipSourcesTitle', "Sources d'XP");
  const hint = trUi(
    game,
    'trustTooltipQuestClaimHint',
    'La confiance des quêtes Rocket est accordée à la réclamation de la récompense.',
  );

  const sourcesHtml = sources
    .map(({ label, xp }) => {
      const xpText = trUi(game, 'trustTooltipSourceXp', '+{xp} XP', { xp: fmt(xp) });
      return `
    <li class="rocket-trust-tooltip-source-row">
      <span class="rocket-trust-tooltip-source-label">${escapeTooltipHtml(label)}</span>
      <span class="rocket-trust-tooltip-source-xp">${escapeTooltipHtml(xpText)}</span>
    </li>`;
    })
    .join('');

  const maxBadge = trustInfo.isMax
    ? `<span class="rocket-trust-tooltip-xp-badge">${escapeTooltipHtml(trUi(game, 'trustMaxLevel', 'Max level reached'))}</span>`
    : '';

  const bodyHtml = `
    <div class="rocket-trust-tooltip">
      <div class="rocket-trust-tooltip-xp-row">
        <span class="rocket-trust-tooltip-xp-label">${escapeTooltipHtml(xpLabel)}</span>
        ${maxBadge}
      </div>
      <div class="rocket-trust-tooltip-progress-track" role="progressbar"
           aria-valuemin="0"
           aria-valuemax="100"
           aria-valuenow="${Math.round(ratioPct)}">
        <div class="rocket-trust-tooltip-progress-fill" style="width: ${ratioPct.toFixed(1)}%;"></div>
      </div>
      <div class="rocket-trust-tooltip-sources-title">${escapeTooltipHtml(sourcesTitle)}</div>
      <ul class="rocket-trust-tooltip-sources">${sourcesHtml}</ul>
      <div class="rocket-trust-tooltip-hint">${escapeTooltipHtml(hint)}</div>
    </div>
  `;

  return { title, bodyHtml };
}
