/** Bar width: share of current loan repaid ((totalDebt - remaining) / totalDebt). */
function computeLoanDebtBarPct(loan: {
  remainingDebt?: number;
  totalDebt?: number;
  active?: boolean;
}): number {
  if (!loan.active) return 0;
  const remaining = Math.max(0, Number(loan.remainingDebt) || 0);
  const total = Math.max(0, Number(loan.totalDebt) || 0);
  if (total <= 0) return 0;
  return Math.min(100, Math.floor(((total - remaining) / total) * 100));
}

function buildLoanStatusText(game: GameRuntime, active: boolean, debtPct: number): string {
  if (active) {
    return trUi(game, 'loanStatusActive', 'In debt: {percent}% repaid', { percent: debtPct });
  }
  return trUi(game, 'loanStatusNone', 'No active debt');
}

/** Stress color: how close remaining debt is to lifetime loan cap. */
function computeLoanDebtCapPct(loan: { remainingDebt?: number }, loanCap: number): number {
  const remaining = Math.max(0, Number(loan.remainingDebt) || 0);
  if (remaining <= 0 || loanCap <= 0) return 0;
  return Math.min(100, Math.floor((remaining / loanCap) * 100));
}

function debtStressFromCapPct(pct: number): RocketDebtStress {
  if (pct <= 0) return 'none';
  if (pct <= 33) return 'low';
  if (pct <= 66) return 'mid';
  return 'high';
}

function uiGameRef(ref: GameRuntime | null | undefined): GameRuntime | undefined {
  return ref ?? undefined;
}

export function trUi(
  game: GameRuntime,
  key: string,
  fallback: string | null = null,
  vars: Record<string, unknown> = {},
): string {
  return uiText(`teamRocket.${key}`, fallback, vars, uiGameRef(game));
}

export function getRocketTrustRankLabel(game: GameRuntime, level?: number): string {
  const lvl = Math.max(1, Math.floor(Number(level ?? game.teamRocketState?.trustLevel) || 1));
  const key = `trustRank${Math.min(5, lvl)}`;
  const fallbacks: Record<string, string> = {
    trustRank1: uiIsEn(game) ? 'Rookie' : 'Recrue',
    trustRank2: uiIsEn(game) ? 'Associate' : 'Associé',
    trustRank3: 'Lieutenant',
    trustRank4: uiIsEn(game) ? 'Captain' : 'Capitaine',
    trustRank5: uiIsEn(game) ? 'Executive' : 'Exécutif',
  };
  if (lvl > 5) {
    return uiIsEn(game) ? `Level ${lvl}` : `Niveau ${lvl}`;
  }
  return trUi(game, key, fallbacks[key] ?? fallbacks.trustRank1);
}

function categoryLabel(game: GameRuntime, c: string): string {
  if (c === 'legendary') return trUi(game, 'categoryLegendary', 'Legendary');
  if (c === 'rare') return trUi(game, 'categoryRare', 'Rare');
  if (c === 'uncommon') return trUi(game, 'categoryUncommon', 'Uncommon');
  return trUi(game, 'categoryCommon', 'Common');
}

function buildKpi(game: GameRuntime, tr: NonNullable<GameRuntime['teamRocketState']>): RocketKpiSnapshot {
  const fmt = (v: number | string) => formatNumber(v);
  const loanCap = game.getRocketLoanCap ? game.getRocketLoanCap() : 0;
  const trustInfo =
    typeof game.getRocketTrustNextLevelInfo === 'function'
      ? game.getRocketTrustNextLevelInfo()
      : {
          currentLevel: tr.trustLevel || 1,
          nextLevel: tr.trustLevel || 1,
          currentXp: 0,
          nextLevelXp: 0,
          ratio: 1,
          isMax: true,
        };
  const trustRatioPct = Math.max(0, Math.min(100, trustInfo.ratio * 100));
  const trustXpProgressLabel = trustInfo.isMax
    ? trUi(game, 'trustMaxLevel', 'Max level reached')
    : trUi(game, 'trustXpProgress', '{current} / {next} XP', {
        current: fmt(trustInfo.currentXp),
        next: fmt(trustInfo.nextLevelXp),
      });
  const rankLabel = getRocketTrustRankLabel(game, trustInfo.currentLevel);
  const trustTooltip = buildRocketTrustTooltip(game, trustInfo, rankLabel);

  return {
    rj: fmt(tr.rj || 0),
    trustLevel: Math.floor(Number(tr.trustLevel) || 1),
    trustXpRatio: trustRatioPct,
    trustXpLabel: trustXpProgressLabel,
    trustIsMax: trustInfo.isMax,
    trustTooltipTitle: trustTooltip.title,
    trustTooltipBody: trustTooltip.bodyHtml,
    loanCap: fmt(loanCap),
    labelRj: trUi(game, 'labelRj', 'Rocket Jeton'),
    labelTrust: trUi(game, 'labelTrust', 'Trust'),
    labelLoanCap: trUi(game, 'labelLoanCap', 'Loan cap'),
  };
}

function buildBank(game: GameRuntime, tr: NonNullable<GameRuntime['teamRocketState']>): RocketBankSnapshot {
  const bank = tr.bank || {};
  const fmt = (v: number | string) => formatNumber(v);
  const trustLevelRate = Math.max(1, Math.floor(Number(tr.trustLevel) || 1));
  const interestStats =
    typeof game.getRocketBankInterestStats === 'function'
      ? game.getRocketBankInterestStats()
      : { instantPerMin: 0, instantPerHour: 0, projection24h: 0 };
  const bankBalance = Math.max(0, Number(bank.balance) || 0);
  const bankCapValue =
    typeof game.getRocketBankBalanceCap === 'function' ? game.getRocketBankBalanceCap() : 0;
  const bankAtCap = bankBalance >= bankCapValue && bankCapValue > 0;

  return {
    rateText: trUi(game, 'bankYield', 'Yield {rate}%/h, paid every minute.', { rate: trustLevelRate }),
    balance: `${fmt(bankBalance)}$`,
    balanceLabel: trUi(game, 'bankBalanceLabel', 'Balance'),
    bankCap: trUi(game, 'bankCapText', '{cap}$ (25% of lifetime earnings)', { cap: fmt(bankCapValue) }),
    bankCapLabel: trUi(game, 'labelBankCap', 'Bank cap'),
    bankAtCapHint: trUi(game, 'bankAtCapHint', 'Cap reached: new credits go to your wallet.'),
    bankAtCap,
    withdrawAvailableText: trUi(game, 'withdrawAvailable', 'Withdraw available'),
    optionsOpen: !!game.rocketBankOptionsOpen,
    autoInjectCombatHalf: !!bank.autoInjectCombatHalf,
    autoInjectInterests: !!bank.autoInjectInterests,
    interestPerMin: `${fmt(interestStats.instantPerMin)}$`,
    interestPerHour: `${fmt(interestStats.instantPerHour)}$`,
    projection24h: `~${fmt(interestStats.projection24h)}$`,
    interestLabelMin: trUi(game, 'interestTrackerInstantPerMin', 'Interest / min'),
    interestLabelHour: trUi(game, 'interestTrackerInstantPerHour', 'Interest / h'),
    interestLabelProj: trUi(game, 'interestTrackerProj24h', 'Projection 24 h'),
    depositButton: trUi(game, 'depositButton', 'Deposit'),
    withdrawButton: trUi(game, 'withdrawButton', 'Withdraw'),
    bankOptionsTitle: trUi(game, 'bankOptionsTitle', 'Bank options'),
    injectCombatHalf: trUi(game, 'injectCombatHalf', 'Inject 50% of combat gains'),
    injectInterests: trUi(game, 'injectInterests', 'Inject interests'),
    bankTitle: trUi(game, 'bankTitle', 'Team Rocket Bank'),
  };
}

function buildLoan(game: GameRuntime, tr: NonNullable<GameRuntime['teamRocketState']>): RocketLoanSnapshot {
  const loan = tr.loan || {};
  const fmt = (v: number | string) => formatNumber(v);
  const loanCap = game.getRocketLoanCap ? game.getRocketLoanCap() : 0;
  const debtBarPct = computeLoanDebtBarPct(loan);
  const debtPct = debtBarPct;
  const debtCapPct = computeLoanDebtCapPct(loan, loanCap);
  const debtStress = debtStressFromCapPct(debtCapPct);
  const loanTaxRate =
    typeof game.getRocketLoanTaxRate === 'function' ? game.getRocketLoanTaxRate(tr.trustLevel) : 0.25;
  const loanTaxRatePct = Math.round(loanTaxRate * 100);
  const active = !!loan.active;

  return {
    loanTitle: trUi(game, 'loanTitle', 'Team Rocket Loan'),
    autoDeductionText: trUi(
      game,
      'loanAutoDeduction',
      'Auto deduction of 50% on gains, excluding bank interest.',
    ),
    maxBorrowText: trUi(game, 'loanMaxBorrow', 'Maximum borrowable: {value}$', { value: fmt(loanCap) }),
    interestRateText: trUi(game, 'loanInterestRate', 'Interest rate: {rate}%', { rate: loanTaxRatePct }),
    debtText: trUi(game, 'loanDebt', 'Debt: {remaining}$ / {total}$', {
      remaining: fmt(loan.remainingDebt || 0),
      total: fmt(loan.totalDebt || 0),
    }),
    debtPct,
    debtBarPct,
    debtCapPct,
    debtStress,
    statusText: buildLoanStatusText(game, active, debtPct),
    active,
    borrowDisabled: !!(loan.active && loan.remainingDebt > 0),
    borrowButton: trUi(game, 'borrowButton', 'Borrow'),
    cardAffordable: !active,
  };
}

function buildStakeableItems(
  game: GameRuntime,
  now: number,
  activeSession: unknown,
): RocketStakeableItemSnapshot[] {
  const stakeableItems =
    typeof game.getRocketStakeableOfferItems === 'function'
      ? game.getRocketStakeableOfferItems(now)
      : [];
  const fmt = (v: number | string) => formatNumber(v);
  const canStake = !activeSession;

  return stakeableItems.map(
    (item: {
      key: string;
      name?: string;
      img?: string;
      icon?: string;
      category?: string;
      amount?: number;
      baseGps?: number;
    }) => {
      const displayName = uiMaybeLocalizeItemName(game, item, item.key, item.name || item.key);
      const iconHtml =
        getItemIconHTML({ name: displayName, img: item.img, icon: item.icon }) || (item.icon || 'OBJ');
      const category = categoryLabel(game, String(item.category ?? ''));
      const ownedCount = fmt(Number(item.amount) || 0);
      const baseGpsFormatted = fmt(Number(item.baseGps) || 0);
      return {
        key: item.key,
        displayName,
        iconHtml,
        categoryLabel: category,
        ownedCount,
        ownedLine: trUi(game, 'stakeOwned', 'Owned: {count}', { count: ownedCount }),
        baseGpsFormatted,
        stakeButton: trUi(game, 'stakeStart', 'Stake x1'),
        canStake,
      };
    },
  );
}

function buildStakingSession(
  game: GameRuntime,
  now: number,
): RocketStakingSessionSnapshot | null {
  const tr = game.teamRocketState;
  if (!tr) return null;
  const staking = tr.staking || {};
  const activeSession = staking.activeSession || null;
  if (!activeSession) return null;

  const cycleMs =
    Number(ROCKET_PUSH_STAKING_CONFIG.cycleMs) > 0
      ? Number(ROCKET_PUSH_STAKING_CONFIG.cycleMs)
      : 30000;
  let cycleProgressMs = 0;
  let cycleLeftMs = cycleMs;
  if (activeSession.nextPhaseEndAt != null && activeSession.currentPhaseDurationMs != null) {
    cycleLeftMs = Math.max(0, Number(activeSession.nextPhaseEndAt) - now);
    cycleProgressMs = Math.max(0, Number(activeSession.currentPhaseDurationMs) - cycleLeftMs);
  } else {
    cycleProgressMs = Math.max(0, (now - (activeSession.startedAt || now)) % cycleMs);
    cycleLeftMs = Math.max(0, cycleMs - cycleProgressMs);
  }
  const phaseDuration = activeSession.currentPhaseDurationMs
    ? Number(activeSession.currentPhaseDurationMs)
    : cycleMs;
  const progressPct = activeSession.currentPhaseDurationMs
    ? Math.max(0, Math.min(100, (cycleProgressMs / phaseDuration) * 100))
    : Math.max(0, Math.min(100, (cycleProgressMs / cycleMs) * 100));

  const riskPct =
    typeof game.getRocketStealRiskPercent === 'function'
      ? game.getRocketStealRiskPercent(activeSession.tier || 1, activeSession)
      : 0;
  const isHighRisk = riskPct > 20;
  const nextTierRisk =
    typeof game.getRocketStakingNextTierRiskRange === 'function'
      ? game.getRocketStakingNextTierRiskRange(activeSession)
      : null;

  const activeSessionItemDef =
    activeSession.itemKey && ALL_ITEMS ? (getAllItem(String(activeSession.itemKey)) ?? {}) : {};
  const activeSessionItemName = uiMaybeLocalizeItemName(
    game,
    activeSessionItemDef,
    activeSession.itemKey,
    activeSession.itemName || activeSession.itemKey || '',
  );

  const fmt = (v: number | string) => formatNumber(v);
  const fmtFloat = (v: number | string) => formatFloatingNumber(Number(v) || 0);

  let nextTierHint = '';
  if (nextTierRisk) {
    nextTierHint = nextTierRisk.capped
      ? trUi(game, 'stakeNextTierRiskCapped', 'Next tier: ~{min}% (95% cap)', { min: nextTierRisk.min })
      : trUi(game, 'stakeNextTierRisk', 'Next tier: {min}-{max}% risk', {
          min: nextTierRisk.min,
          max: nextTierRisk.max,
        });
  }

  return {
    sessionTitle: trUi(game, 'stakeSessionTitle', 'Push Your Luck Session'),
    objectLine: trUi(game, 'stakeSessionObjectLine', 'Item: {item} | Category: {category}', {
      item: activeSessionItemName,
      category: categoryLabel(game, String(activeSession.category ?? '')),
    }),
    accumulatedText: trUi(game, 'stakeAccumulated', 'RJ accumulated: {value}', {
      value: fmt(Math.floor(activeSession.accruedRJ || 0)),
    }),
    gpsText: trUi(game, 'stakeGps', 'GPS: {gps} RJ/s (x{mult})', {
      gps: fmtFloat(activeSession.currentGps || 0),
      mult: fmtFloat(activeSession.multiplier || 1),
    }),
    riskText: trUi(game, 'stakeRiskPhase', 'Theft risk end of phase: {risk}%', { risk: riskPct }),
    riskVariant: isHighRisk ? 'danger' : 'warn',
    isHighRisk,
    nextTierHint,
    timerText: formatTimeString(cycleLeftMs),
    progressPct,
    recoverButton: trUi(game, 'stakeRecover', 'RECOVER'),
  };
}

function buildStealFeedback(game: GameRuntime): RocketStealFeedbackSnapshot | null {
  const tr = game.teamRocketState;
  if (!tr) return null;
  const staking = tr.staking || {};
  const stealFeedback =
    staking.lastStealFeedback && typeof staking.lastStealFeedback === 'object'
      ? staking.lastStealFeedback
      : null;
  if (!stealFeedback) return null;

  const fmt = (v: number | string) => formatNumber(v);
  const stealFeedbackItemName = uiMaybeLocalizeItemName(
    game,
    stealFeedback.itemKey ? getAllItem(String(stealFeedback.itemKey)) || {} : {},
    stealFeedback.itemKey || '',
    stealFeedback.itemName || 'Item',
  );

  return {
    title: trUi(game, 'stealTitle', 'Item stolen by Team Rocket'),
    body: trUi(game, 'stealBody', '{item} was stolen at tier {tier} (risk {risk}%).', {
      item: stealFeedbackItemName,
      tier: stealFeedback.tier || 1,
      risk: stealFeedback.riskPercent || 0,
    }),
    lossText: trUi(game, 'stealLoss', 'Session loss: {value} RJ', {
      value: fmt(stealFeedback.lostRJ || 0),
    }),
    acknowledgeButton: trUi(game, 'acknowledge', 'Understood'),
  };
}

function buildStaking(game: GameRuntime, now: number): RocketStakingSnapshot {
  const tr = game.teamRocketState!;
  const staking = tr.staking || {};
  const activeSession = staking.activeSession || null;
  const nextRotateAt = Math.max(0, Number(staking.nextOfferRotateAt) || 0);
  const rotateLeftMs = Math.max(0, nextRotateAt - now);
  const rotateLeftText = formatTimeString(rotateLeftMs);
  const stakeableItems = buildStakeableItems(game, now, activeSession);
  const waitingNextSelection =
    !activeSession && stakeableItems.length === 0 && rotateLeftMs > 0;

  let emptyMessage: string | null = null;
  if (stakeableItems.length === 0) {
    emptyMessage = waitingNextSelection
      ? trUi(game, 'stakeSelectionLocked', 'Selection locked. Next selection in {time}.', {
          time: rotateLeftText,
        })
      : trUi(game, 'stakeNoItem', 'No stakeable item in inventory.');
  }

  const timerText = activeSession
    ? trUi(
        game,
        'stakingTimerActive',
        'Session active: risk checked each phase (25-35 s) | Next possible selection in {time}',
        { time: rotateLeftText },
      )
    : trUi(
        game,
        'stakingTimerIdle',
        'Random rotation: 3 items | After a pick, next selection in at least 15 min | {time}',
        { time: rotateLeftText },
      );

  return {
    sectionTitle: trUi(game, 'stakingSectionTitle', 'Push Your Luck Staking'),
    timerText,
    session: buildStakingSession(game, now),
    noSessionText: trUi(game, 'stakeNoSession', 'No active session. Start with an item.'),
    stakeableItems,
    emptyMessage,
    stealFeedback: buildStealFeedback(game),
  };
}

function buildCasinoCard(game: GameRuntime, tr: NonNullable<GameRuntime['teamRocketState']>): RocketCasinoCardSnapshot {
  const fmt = (v: number | string) => formatNumber(v);
  const trustLevelLabel = getRocketTrustRankLabel(game);
  const casinoCfg = ROCKET_CASINO_CONFIG ?? { lineCostRJ: 250, defaultActivePaylines: 8 };
  const casinoMaxLines = 8;
  const casinoLines = Math.max(
    1,
    Math.min(casinoMaxLines, Math.floor(Number(casinoCfg.defaultActivePaylines) || casinoMaxLines)),
  );
  const casinoBaseLineCost = Math.max(1, Math.floor(Number(casinoCfg.lineCostRJ) || 250));
  let casinoSpinCost = casinoBaseLineCost * casinoLines;
  if (game.upgrades && game.upgrades.casinoRoyal) {
    const reduction = (game.upgrades.casinoRoyal.level || 0) * 0.05;
    casinoSpinCost = Math.max(1, Math.floor(casinoSpinCost * (1 - reduction)));
  }
  const casinoSpinsAvailable = Math.floor(Math.max(0, Number(tr.rj) || 0) / Math.max(1, casinoSpinCost));

  return {
    sectionTitle: trUi(game, 'casinoSectionTitle', 'Rocket Casino'),
    machineTitle: trUi(game, 'casinoMachineTitle', 'Rocket Slot Machine'),
    machineDesc: trUi(
      game,
      'casinoMachineDesc',
      'Animated reels, RJ bets, local spin history and reward table.',
    ),
    levelLine: trUi(game, 'casinoMachineLevel', 'Level: {level} | Trust XP: {xp}', {
      level: trustLevelLabel,
      xp: fmt(tr.trustXp || 0),
    }),
    hasSpins: casinoSpinsAvailable > 0,
    spinsCountText:
      casinoSpinsAvailable > 0
        ? trUi(game, 'casinoSpinsAvailable', '{count} spins available', {
            count: fmt(casinoSpinsAvailable),
          })
        : trUi(game, 'casinoSpinsAvailableNone', 'No spin available (need {cost} RJ)', {
            cost: fmt(casinoSpinCost),
          }),
    spinCostText: trUi(game, 'casinoSpinCost', 'Cost: {cost} RJ per spin ({lines} lines)', {
      cost: fmt(casinoSpinCost),
      lines: casinoLines,
    }),
    openButton: trUi(game, 'casinoOpenButton', 'Open slot machine'),
  };
}

