export function buildRocketSnapshot(game: GameRuntime): RocketSnapshot {
  if (!game.teamRocketState) return EMPTY_ROCKET_SNAPSHOT;
  const tr = game.teamRocketState;
  const now = Date.now();
  return {
    kpi: buildKpi(game, tr),
    bank: buildBank(game, tr),
    loan: buildLoan(game, tr),
    staking: buildStaking(game, now),
    casino: buildCasinoCard(game, tr),
  };
}

export function buildRocketRealtimeSnapshot(game: GameRuntime): RocketRealtimeSnapshot {
  if (!game.teamRocketState) return EMPTY_ROCKET_REALTIME;
  const tr = game.teamRocketState;
  const fmt = (v: number | string) => formatNumber(v);
  const bank = tr.bank || {};
  const loan = tr.loan || {};
  const staking = tr.staking || {};
  const now = Date.now();

  const loanCap = game.getRocketLoanCap ? game.getRocketLoanCap() : 0;
  const debtBarPct = computeLoanDebtBarPct(loan);
  const debtCapPct = computeLoanDebtCapPct(loan, loanCap);
  const debtStress = debtStressFromCapPct(debtCapPct);
  const loanActive = !!loan.active;
  const loanStatusText = buildLoanStatusText(game, loanActive, debtBarPct);

  const interestStats =
    typeof game.getRocketBankInterestStats === 'function'
      ? game.getRocketBankInterestStats()
      : { instantPerMin: 0, instantPerHour: 0, projection24h: 0 };

  const nextRotateAt = Math.max(0, Number(staking.nextOfferRotateAt) || 0);
  const rotateLeftMs = Math.max(0, nextRotateAt - now);
  const rotateLeftText = formatTimeString(rotateLeftMs);
  const session = staking.activeSession || null;

  const stakingTimerText = session
    ? trUi(
        game,
        'stakingTimerActive',
        'Session active: risk checked each phase (25-35 s) | Next possible selection in {time}',
        { time: rotateLeftText },
      )
    : trUi(
        game,
        'stakingTimerIdle',
        'Random rotation: 3 items | After a pick, next selection in at least 15 min | {time}',
        { time: rotateLeftText },
      );

  let sessionRealtime: RocketStakingSessionSnapshot | null = null;
  let stakingNeedsFullRebuild = !session;

  if (session) {
    sessionRealtime = buildStakingSession(game, now);
    stakingNeedsFullRebuild = false;
  }

  return {
    rj: fmt(tr.rj || 0),
    bankBalance: `${fmt(bank.balance || 0)}$`,
    interestPerMin: `${fmt(interestStats.instantPerMin)}$`,
    interestPerHour: `${fmt(interestStats.instantPerHour)}$`,
    projection24h: `~${fmt(interestStats.projection24h)}$`,
    loanDebtText: trUi(game, 'loanDebt', 'Debt: {remaining}$ / {total}$', {
      remaining: fmt(loan.remainingDebt || 0),
      total: fmt(loan.totalDebt || 0),
    }),
    loanDebtBarPct: debtBarPct,
    loanDebtCapPct: debtCapPct,
    loanDebtStress: debtStress,
    loanStatusText,
    loanActive,
    loanBorrowDisabled: !!(loan.active && loan.remainingDebt > 0),
    loanCardAffordable: !loanActive,
    stakingTimerText,
    stakingNeedsFullRebuild,
    session: sessionRealtime,
  };
}

